import { expect, it } from 'vitest';
// Expected values are generated by scripts/RuleCompleteOracle.kt with the pinned upstream class.
import cases from './source-rule-complete.cases.json';
import { completeRule, completeSourceRules } from './source-rule-complete';
import type { Source } from './model';

it('matches the pinned upstream Kotlin RuleComplete output for simple and excluded rules', () => {
  for (const item of cases) expect(completeRule(item.rule, item.preRule ?? undefined, item.type as 1 | 2 | 3), JSON.stringify(item)).toBe(item.expected);
});

it('completes only upstream editor fields and retains scripts, unknown fields and the original draft', () => {
  const source: Source = {
    bookSourceName: 'Rule fixture', bookSourceUrl: 'https://complete.test', searchUrl: '/search', mainJs: 'function search() {}',
    ruleSearch: { bookList: '.books', name: '.title', bookUrl: 'a', coverUrl: 'img', custom: 'untouched' },
    ruleExplore: { bookList: '$.books', name: '$.name', bookUrl: 'url' },
    ruleBookInfo: { init: 'article', name: 'h1', tocUrl: 'a', coverUrl: 'img', downloadUrls: '.download' },
    ruleToc: { chapterList: 'a', chapterName: 'span', chapterUrl: 'a', nextTocUrl: 'a.next', updateTime: '.time', formatJs: 'result' },
    ruleContent: { content: '.body', subContent: 'p', title: 'h1', nextContentUrl: 'a', replaceRegex: 'x##y', webJs: 'result', sourceRegex: 'x' },
    ruleReview: { summaryListRule: 'div' }, extra: { original: true },
  };
  const before = JSON.stringify(source), value = completeSourceRules(source);
  expect(value.ruleSearch).toEqual({ bookList: '.books', name: '.title@text', bookUrl: 'a@href', coverUrl: 'img@src', custom: 'untouched' });
  expect(value.ruleExplore).toEqual(source.ruleExplore);
  expect(value.ruleBookInfo).toMatchObject({ init: 'article', name: 'h1@text', tocUrl: 'a@href', coverUrl: 'img@src', downloadUrls: '.download@text' });
  expect(value.ruleToc).toEqual({ chapterList: 'a', chapterName: 'span@text', chapterUrl: 'a@href', nextTocUrl: 'a.next@href', updateTime: '.time', formatJs: 'result' });
  expect(value.ruleContent).toEqual({ content: '.body@text', subContent: 'p@text', title: 'h1@text', nextContentUrl: 'a@href', replaceRegex: 'x##y', webJs: 'result', sourceRegex: 'x' });
  expect(value.ruleReview).toEqual(source.ruleReview); expect(value.mainJs).toBe(source.mainJs); expect(value.extra).toEqual(source.extra);
  expect(JSON.stringify(source)).toBe(before); expect(completeSourceRules(value)).toEqual(value);
});
